// Standalone visual/support adapter only: no heal, portal, save, or recovery authority.
import{scope,sha,dataRecord,footData,loadPlayers}from'./center-common.mjs';
import{centerVisibleView as visibleView}from'./center-visible-view.mjs';
import{CENTER_CONTRACT as C}from'../center-interior/fixed-contract.mjs';
import{loadCenterInteriorInputs}from'../center-interior/load.mjs';
import{CenterInteriorScene}from'../center-interior/center-interior-scene.mjs';
const assetModuleURL=import.meta.url;const brands=new WeakMap(),base=new URL('../center-interior/',assetModuleURL),fields=['mapId','revision','state','imageSHA','maskSHA','foot','facing'];
const identity=Object.freeze({mapId:'world:hub:S4',revision:'CENTER_R4_COUNTER_ROOT_SELECTED_R1',state:'CENTER_R4',imageSHA:C.inputs.image.sha256,maskSHA:C.inputs.safe.sha256});
function handle(bank,owner=false,signal){bank.refs++;let dead=false;const live=()=>!dead&&!signal?.aborted&&bank.bytes!==null;const safe=(foot,state='CENTER_R4')=>{try{const[x,y]=footData(foot);return live()&&state==='CENTER_R4'&&x>=0&&y>=0&&x<768&&y<576&&bank.bytes[y*768+x]===1}catch{return false}};const describe=(foot,facing,state='CENTER_R4')=>{const f=footData(foot);if(!safe(f,state)||!['up','down','left','right'].includes(facing))throw Error('CENTER_SAFE_POSE');return{...identity,foot:f,facing}};const validate=pose=>{try{const p=dataRecord(pose,fields);return Object.entries(identity).every(([k,v])=>p[k]===v)&&safe(p.foot,p.state)&&['up','down','left','right'].includes(p.facing)}catch{return false}};const dispose=()=>{if(dead)return;dead=true;signal?.removeEventListener('abort',dispose);if(owner)bank.accept=false;if(--bank.refs===0)bank.bytes=null};signal?.addEventListener('abort',dispose,{once:true});if(signal?.aborted)dispose();return Object.freeze({get pinsVerified(){return live()},safe,describe,validate,...(owner?{leaseToken:bank.token}:{}),dispose})}
async function createSupport(bytes,signal){const owned=new Uint8Array(bytes).slice();if(owned.length!==768*576||await sha(owned)!==identity.maskSHA)throw Error('CENTER_MASK_PIN');const bank={bytes:owned,refs:0,accept:true,token:Object.freeze({})};brands.set(bank.token,bank);return handle(bank,true,signal)}
function borrow(token){const bank=brands.get(token);if(!bank||!bank.accept||bank.bytes===null)throw Error('CENTER_FOREIGN_OR_CLOSED_LEASE');return handle(bank)}
export async function prepareCenterSupport(options={}){const s=scope(options);let support;try{support=await createSupport(await s.pinned(new URL('center.safe.u8',base),identity.maskSHA,768*576),options.signal);s.check();return support}catch(e){support?.dispose();throw e}finally{s.dispose()}}
export async function prepareCenterPresentation(options={}){const{appearance='boy',canvasFactory=(w,h)=>new OffscreenCanvas(w,h)}=options;if(!['boy','girl'].includes(appearance))throw Error('CENTER_APPEARANCE');const d=Object.getOwnPropertyDescriptor(options,'supportLeaseToken');if(d&&(!d.enumerable||!Object.hasOwn(d,'value'))||!d&&'supportLeaseToken'in options)throw Error('CENTER_LEASE_DESCRIPTOR');const s=scope(options),canvases=[],make=(w,h)=>{s.check();const c=canvasFactory(w,h);canvases.push(c);return c};let inputs,support;
s.onCleanup(()=>support?.dispose());s.onCleanup(()=>inputs?.dispose());s.onCleanup(()=>{for(const c of canvases)try{c.width=c.height=1}catch{}canvases.length=0});
try{s.check();if(d&&d.value!==null&&d.value!==undefined)support=borrow(d.value);inputs=await loadCenterInteriorInputs({fetcher:s.wrappedFetch,decode:options.decode,signal:options.signal});s.onCleanup(()=>inputs.dispose());s.check();if(!support){support=await createSupport(inputs.safe,options.signal);s.onCleanup(()=>support.dispose())}inputs.safe=null;s.check();const playerFrames=await loadPlayers(s,appearance,make),assets={...inputs.assets,playerFrames};return visibleView({s,support,appearance,make,drawNative:(ctx,v)=>{const facade={assets,layout:inputs.layout,provider:{snapshot:()=>({foot:v.pose.foot,facing:v.pose.facing})},stopped:!v.walking};return CenterInteriorScene.prototype.draw.call(facade,ctx,v.clock)}})}catch(e){s.dispose();throw e}}
